node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1180,height:980}});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002');
 await page.getByRole('button',{name:/Start a run/}).click();
 await page.waitForTimeout(420);
 const playing=await page.locator('#status').innerText();
 await page.keyboard.press('ArrowDown');
 await page.waitForTimeout(220);
 const statusAfterMove=await page.locator('#status').innerText();
 const dimensions=await page.locator('canvas').evaluate(c=>({width:c.width,height:c.height,cssWidth:c.clientWidth,cssHeight:c.clientHeight}));
 await page.getByRole('button',{name:'Pause game'}).click();
 const paused=await page.locator('#status').innerText();
 console.log(JSON.stringify({playing,statusAfterMove,paused,dimensions,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
